import * as React from 'react';

/**
 * POI type pins — the canonical flood-ops POI markers (Flood Management, Figma
 * cWjEbSNpZCC7tNhZc2CikU · 245-34136 Assembly Point, 245-34127 Rain Tower):
 * a rounded-square speech-bubble head (white 2.5 stroke) carrying a white
 * domain glyph, floating above a small colour-matched anchor dot.
 *
 * Two forms are exported for each type so the SAME artwork is used on the map
 * AND in the table listing (design-consistency across every module):
 *   • `assemblyPointPinDataUri()` / `rainTowerPinDataUri()` — map markers
 *     (recolorable data-URI SVG; drop straight into `MapMarker.iconUrl`).
 *   • `<AssemblyPointGlyph/>` / `<RainTowerGlyph/>` — the inner glyph alone as
 *     a `currentColor` React icon, for list ICON columns / chips / detail.
 *
 * Colours are hex by necessity (a data-URI `<img>` can't resolve `var()`); the
 * defaults mirror the Figma source and DS tokens (annotated inline).
 */

export const POI_ASSEMBLY_COLOR = '#063F39'; // coherence-allow — Figma assembly-point teal (deep flood-ops green)
export const POI_RAIN_COLOR = '#0072D6';     // coherence-allow — Figma rain-tower blue (== --status-info)

