const cache = new Map<string, string>();

/** Compose the full pin (body + glyph + anchor dot) into a data URI. */
function composePin(key: string, color: string, glyph: string, glyphTransform: string): string {
  const hit = cache.get(key);
  if (hit) return hit;
  const svg =
    `<svg width="36" height="54" viewBox="0 0 36 54" fill="none" xmlns="http://www.w3.org/2000/svg">` +
    `<g filter="url(#s)">` +
    `<path d="${PIN_BODY}" fill="${color}" stroke="white" stroke-width="2.5"/>` +
    `<g transform="${glyphTransform}">${glyph}</g>` +
    `</g>` +
    // anchor dot: colour-matched disc + white ring, centred at (18, 49)
    `<circle cx="18" cy="49" r="2.9" fill="${color}"/>` +
    `<circle cx="18" cy="49" r="3.9" stroke="white" stroke-width="2"/>` +
    `<defs><filter id="s" x="-2" y="0" width="40" height="52" filterUnits="userSpaceOnUse" color-interpolation-filters="sRGB"><feDropShadow dx="0" dy="2" stdDeviation="2" flood-opacity="0.22"/></filter></defs>` +
    `</svg>`;
  const uri = `data:image/svg+xml,${encodeURIComponent(svg)}`;
  cache.set(key, uri);
  return uri;
}

/** Assembly-point map pin (teal, building glyph). */
export function assemblyPointPinDataUri(color = POI_ASSEMBLY_COLOR): string {
  // glyph 18×14.46 centred in the bubble (~centre 17.7,18)
  return composePin(`ap-${color}`, color, ASSEMBLY_GLYPH, 'translate(8.7 11)');
}

/** Rain-tower map pin (blue, rain-sensor glyph). */
export function rainTowerPinDataUri(color = POI_RAIN_COLOR): string {
  // glyph 11.82×16.47 centred in the bubble
  return composePin(`rt-${color}`, color, RAIN_GLYPH, 'translate(11.8 10)');
}

/* ── Inspector map pin (Figma 245-34249) ─────────────────────────────────────
 * A blue-ringed circular avatar (person glyph) with a small location badge at
 * the top and a blue anchor dot below. Recolorable via `color`.
 */
const inspectorCache = new Map<string, string>();
export function inspectorPinDataUri(color = POI_RAIN_COLOR): string {
  const hit = inspectorCache.get(color);
  if (hit) return hit;
  const svg =
    `<svg width="40" height="60" viewBox="0 0 40 60" fill="none" xmlns="http://www.w3.org/2000/svg">` +
    `<g filter="url(#is)">` +
    // avatar disc: white fill + coloured ring
    `<circle cx="20" cy="20" r="16" fill="white" stroke="${color}" stroke-width="3"/>` +
    // person glyph (head + shoulders), coloured
    `<circle cx="20" cy="16.5" r="4.2" fill="${color}"/>` +
    `<path d="M11.5 27.5c0-4.2 3.8-6.8 8.5-6.8s8.5 2.6 8.5 6.8a16 16 0 0 1-17 0z" fill="${color}"/>` +
    // top location badge
    `<circle cx="20" cy="3.6" r="3.4" fill="${color}" stroke="white" stroke-width="1.5"/>` +
    `<circle cx="20" cy="3.6" r="1.2" fill="white"/>` +
    `</g>` +
    // stem + anchor dot
    `<line x1="20" y1="36" x2="20" y2="52" stroke="${color}" stroke-width="1.5"/>` +
    `<circle cx="20" cy="54" r="2.9" fill="${color}"/>` +
    `<circle cx="20" cy="54" r="3.9" stroke="white" stroke-width="2"/>` +
    `<defs><filter id="is" x="0" y="0" width="40" height="42" filterUnits="userSpaceOnUse" color-interpolation-filters="sRGB"><feDropShadow dx="0" dy="2" stdDeviation="2" flood-opacity="0.22"/></filter></defs>` +
    `</svg>`;
  const uri = `data:image/svg+xml,${encodeURIComponent(svg)}`;
  inspectorCache.set(color, uri);
  return uri;
}
/** Inspector pin natural size + anchor (dot centre). */
export const INSPECTOR_PIN_SIZE: [number, number] = [40, 60];
export const INSPECTOR_PIN_ANCHOR: [number, number] = [20, 54];

